UPDATE gamification_runtime_config
SET status = 'REJECTED', change_reason = #{reason}, version = version + 1
WHERE id = #{id} AND status = 'PENDING_APPROVAL' AND version = #{expectedVersion}

UPDATE gamification_runtime_config
SET status = 'CANCELLED', change_reason = #{reason}, version = version + 1
WHERE id = #{id} AND status = 'SCHEDULED' AND version = #{expectedVersion}

UPDATE gamification_runtime_config
SET status = 'ARCHIVED', archived_at = #{archivedAt}, version = version + 1
WHERE id = #{id} AND status = 'ACTIVE' AND version = #{expectedVersion}
